"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def CountVowels(text):
    vowel_counts = {}
    vowel_counts['a'] = 0
    vowel_counts['e'] = 0
    vowel_counts['i'] = 0
    vowel_counts['o'] = 0
    vowel_counts['u'] = 0
    for __reserved_keyword__char in str(text).lower():
        if (__reserved_keyword__char in vowel_counts):
            vowel_counts[__reserved_keyword__char] = (vowel_counts[__reserved_keyword__char] + 1)
    return vowel_counts

print(CountVowels("This is a sentence that contains vowels"))
